import{z as d,x as c,o as s,c as B,q as E,j as n,D as t,d as r,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"缓冲与脏页","description":"","frontmatter":{"title":"缓冲与脏页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/buffer-dirty.md","filePath":"cs/buffer-dirty.md","lastUpdated":1791063341000}'),p={name:"cs/buffer-dirty.md"};function A(m,e,h,f,C,D){const o=c("Mermaid");return s(),B("div",null,[e[2]||(e[2]=E('<h1 id="缓冲与脏页" tabindex="-1">缓冲与脏页 <a class="header-anchor" href="#缓冲与脏页" aria-label="Permalink to &quot;缓冲与脏页&quot;">​</a></h1><div class="epigraph"><p>磁盘块在内存里有一份缓存；写先标脏，稍后才回写。崩溃时内存与介质可以不一致。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；McKusick 等对 Unix 缓冲缓存的整理</footer></div><p><a href="/cs/mount-super">上一课</a>让读写落到块号。<a href="/cs/mmap">mmap</a> 与 <a href="/cs/demand-paging">按需调页</a>已经把文件页放进帧。缺口是统一承认：<strong>页 Cache / 缓冲缓存</strong>是磁盘的 Cache，脏位表示比介质新。数据库栏的 <a href="/cs/wal">WAL</a> 正是在这个前提下谈日志先行。本课只钉缓冲与脏，不选磁盘臂算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次 <code>write</code> 若都同步落盘，管道式小写会把吞吐打穿。若只改内存，断电丢数据。缺口不是新的 inode 字段，而是策略：写进帧并标脏；读命中则不访盘；回写可由定时器、内存压力（<a href="/cs/page-replace">置换</a>）或 <code>fsync</code> 触发。同一物理块不应在缓冲里有两份互相不知道的副本。</p><p>本课不把 write-back 与 write-through 的微架构 Cache 课再推一遍；对象换成磁盘块。</p><p><span class="marginnote">直觉类比：脏页像收银台的暂记账本——顾客买东西先记账（写内存），钱还没进保险柜（磁盘）。记账快所以收银快，但断电时没誊清的条目就丢了；<code>fsync</code> 就是「立刻誊进保险柜并当面点清」的强制命令。</span></p><p><span class="marginnote">脏页是还没到稳定介质的字节。<code>fsync</code> 要求该文件相关脏页与必要元数据到达持久存储。组提交与延迟分配是优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查页 Cache，无则分配帧、读盘、插入。写：在 Cache 中修改，标脏。置换选到脏页必须先写盘。元数据（inode、目录）同样走缓冲，崩溃可留下「目录项在、inode 未分」或相反，这是 fsck 与日志要补的，本课只暴露不一致可能。</p>',10)),(s(),n(l,null,{default:t(()=>[i(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RW%5B%22read%2Fwrite%2Fmmap%22%5D%20--%3E%20CACHE%5B%22%E9%A1%B5%20Cache%22%5D%0A%20%20CACHE%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%3A%20%E4%B8%8D%E8%AE%BF%E7%9B%98%22%5D%0A%20%20CACHE%20--%3E%20DIRTY%5B%22%E5%86%99%E5%88%99%E8%84%8F%22%5D%0A%20%20DIRTY%20--%3E%20WB%5B%22%E5%9B%9E%E5%86%99%20%2F%20fsync%20%2F%20%E7%BD%AE%E6%8D%A2%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[r("缓冲把磁盘的高延迟从大多数 "),a("code",null,"read"),r(" 里拿掉，让"),a("a",{href:"/cs/scheduling-metrics"},"调度指标"),r("里的 I/O 等待下降。它也让 mmap 与 "),a("code",null,"read"),r(" 看见同一帧成为可能：统一 Cache。脏页是正确性与性能的交界：OS 允许短暂不一致；数据库用 WAL 在更高层再加一条顺序。本栏不把关系库的 REDO 写进文件系统课。")],-1)),e[5]||(e[5]=a("p",null,"与关中断锁的关系：Cache 索引是共享结构，下半部完成 DMA 后要把页标有效，锁规则沿用同步课。",-1)),e[6]||(e[6]=a("p",null,"下图回答一个具体问题：一页从干净到脏再回到干净，会经过哪些状态、谁触发转移。",-1)),(s(),n(l,null,{default:t(()=>[i(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAD%5B%22%E9%A6%96%E6%AC%A1%E8%AF%BB%EF%BC%9A%E5%B8%A7%E8%A3%85%E5%85%A5%EF%BC%8C%E9%A1%B5%E5%B9%B2%E5%87%80%22%5D%20--%3E%20W%5B%22write%20%E6%88%96%20mmap%20%E5%86%99%E5%85%A5%EF%BC%9A%E6%A0%87%E8%84%8F%22%5D%0A%20%20W%20--%3E%20D%5B%22%E8%84%8F%EF%BC%9A%E5%86%85%E5%AD%98%E6%AF%94%E4%BB%8B%E8%B4%A8%E6%96%B0%22%5D%0A%20%20D%20--%3E%7C%22%E5%AE%9A%E6%97%B6%E5%99%A8%E5%88%B0%E7%82%B9%22%7C%20WB%5B%22%E5%9B%9E%E5%86%99%22%5D%0A%20%20D%20--%3E%7C%22%E5%86%85%E5%AD%98%E5%8E%8B%E5%8A%9B%EF%BC%9A%E7%BD%AE%E6%8D%A2%E9%80%89%E4%B8%AD%22%7C%20WB%0A%20%20D%20--%3E%7C%22%E5%BA%94%E7%94%A8%E8%B0%83%20fsync%22%7C%20WB%0A%20%20WB%20--%3E%20C%5B%22%E4%BB%8B%E8%B4%A8%E5%B7%B2%E6%96%B0%EF%BC%9A%E9%A1%B5%E5%8F%98%E5%B9%B2%E5%87%80%EF%BC%8C%E4%BB%8D%E7%95%99%20Cache%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=E('<p><span class="marginnote">数字实例：顺序写 1 GB 文件，<code>write</code> 只是把数据拷进页 Cache，按内存速度微秒级完成；真正落盘由后台按磁盘速度（每秒几十 MB 到几 GB 不等）慢慢进行。若一直不 <code>fsync</code>，断电最多丢掉最后一个回写周期（常见约 30 秒）内的修改。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 O_DIRECT 绕过 Cache 的全部语义，不把电池后备写缓存当默认硬件。也不保证 <code>write</code> 返回即持久——那正是脏页的含义。下一课才问：许多脏页要写时，请求以什么顺序送向设备。</p><p>写回顺序若先数据后 inode 大小，崩溃可能泄露旧数据；日志文件系统用事务把元数据捆在一起，本课只承认问题存在。</p><p>后课默认：内存可以比磁盘新。回写与读请求如何排队到磁头或闪存，下一课磁盘调度。</p><p><span class="marginnote">常见误区：初学者以为 <code>write</code> 正常返回就等于数据已在磁盘上。它只保证进了页 Cache 并标脏；掉电或内核崩溃就可能丢。要持久必须 <code>fsync</code>，且数据与元数据的落盘顺序还要对——这正是数据库强调 WAL 先行的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文件页经统一 Cache；写标脏，稍后回写。</li><li>崩溃时允许不一致；fsync 是显式持久。</li><li>WAL 假定本课这个缺口已经在。</li><li>出处：Silberschatz et al., <em>OSC</em>；McKusick, Bostic, Karels, Quarterman, <em>The Design and Implementation of the 4.4BSD Operating System</em>。</li></ul>',8))])}const b=d(p,[["render",A]]);export{_ as __pageData,b as default};
